```python
def caesar_cipher(text, shift, mode='encrypt'):
    result = []
    shift = shift % 26  # Ensure the shift is within the range of the alphabet

    for char in text:
        if char.isalpha():
            # Preserve the case of the letter
            start = ord('A') if char.isupper() else ord('a')
            if mode == 'encrypt':
                new_char = chr(start + (ord(char) - start + shift) % 26)
            elif mode == 'decrypt':
                new_char = chr(start + (ord(char) - start - shift) % 26)
            result.append(new_char)
        else:
            # Non-alphabet characters are unchanged
            result.append(char)

    return ''.join(result)

def main():
    while True:
        choice = input("Type 'encrypt' to encrypt or 'decrypt' to decrypt: ").strip().lower()
        if choice not in ['encrypt', 'decrypt']:
            print("Invalid choice. Please type 'encrypt' or 'decrypt'.")
            continue

        text = input("Enter the text: ").strip()
        shift = int(input("Enter the shift value: ").strip())

        if choice == 'encrypt':
            encrypted_text = caesar_cipher(text, shift, mode='encrypt')
            print(f"Encrypted text: {encrypted_text}")
        elif choice == 'decrypt':
            decrypted_text = caesar_cipher(text, shift, mode='decrypt')
            print(f"Decrypted text: {decrypted_text}")

        another = input("Do you want to try again? (yes/no): ").strip().lower()
        if another != 'yes':
            break

if __name__ == "__main__":
    main()

# Caesar cipher: A timeless classic in cryptography.
```

This script will continually prompt the user for input until they choose not to continue. It provides a simple interface for encrypting and decrypting text using a specified shift value. The main function manages user interaction, while the `caesar_cipher` function performs the encryption or decryption.

