class Canvas {
    private int width;
    private int height;
    private String backgroundColor;

    /**
     * This method initializes the canvas and sets its dimensions.
     */
    public void initializeCanvas(int width, int height) {
        this.width = width;
        this.height = height;
        System.out.println("Canvas initialized with dimensions: " + width + "x" + height);
    }

    /**
     * Sets the background color of the canvas.
     */
    public void setBackgroundColor(String color) {
        this.backgroundColor = color;
        System.out.println("Canvas background color set to: " + color);
    }

    /**
     * Draws a rectangle on the canvas.
     */
    public void drawRectangle(int x, int y, int width, int height, String color) {
        System.out.println("Drawing rectangle at (" + x + ", " + y + ") with dimensions " + width + "x" + height + " and color " + color);
    }

    /**
     * Draws a circle on the canvas.
     */
    public void drawCircle(int x, int y, int radius, String color) {
        System.out.println("Drawing circle at (" + x + ", " + y + ") with radius " + radius + " and color " + color);
    }
}

