Here's a C code snippet using libcurl to perform a GET request to "https://api.example.com/data" and print the response to the console. The comments are in English and in capital letters, as requested.

```c
#include <stdio.h>
#include <stdlib.h>
#include <curl/curl.h>

// CALLBACK FUNCTION TO HANDLE THE DATA RECEIVED FROM THE SERVER
size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    // CALCULATE THE REAL SIZE OF THE INCOMING BUFFER
    size_t totalSize = size * nmemb;
    // APPEND THE INCOMING DATA TO THE USER-DEFINED BUFFER
    strncat((char *)userp, (char *)contents, totalSize);
    // RETURN THE SIZE OF THE DATA HANDLED
    return totalSize;
}

int main(void) {
    // DECLARE A CURL HANDLE
    CURL *curl;
    // VARIABLE TO STORE THE CURL OPERATION RESULT
    CURLcode res;

    // INITIALIZE A BUFFER TO STORE THE RESPONSE
    char responseBuffer[10000] = {0};

    // INITIALIZE A CURL SESSION
    curl = curl_easy_init();
    if(curl) {
        // SET THE URL FOR THE GET REQUEST
        curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/data");
        // SPECIFY THE CALLBACK FUNCTION TO HANDLE THE RESPONSE DATA
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
        // SET THE USER-DEFINED BUFFER AS THE DATA TARGET
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, responseBuffer);

        // PERFORM THE GET REQUEST
        res = curl_easy_perform(curl);

        // CHECK FOR ERRORS IN THE REQUEST
        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        else
            // PRINT THE RESPONSE DATA TO THE CONSOLE
            printf("Response:\n%s\n", responseBuffer);

        // CLEAN UP THE CURL SESSION
        curl_easy_cleanup(curl);
    }
    return 0;
}
```

